/* شعارات خاصة بالمشتركين: يظهر الشعار فقط لصاحب الكود، ويعمل بدون إنترنت.
   الكود لا يُخزَّن هنا؛ فقط بصمته (PBKDF2) حتى لا يمكن استخراجه من الملف. */
(function () {
  'use strict';
  var BRANDS = {
    "1265d32bea6f7767be92f98e5e322d2e": { name: "Mustafa Al hafiz", logoDark: "data:image/png;base64,", logo: "data:image/png;base64," },
    "0aedf005048c5331f32e45075d2e1d6a": { name: "Karar Aledani", homeLogo: "data:image/webp;base64,",
      theme: { hex: { "#ee6200": "#8a1c2f", "#ff9a00": "#b8892e", "#2a1400": "#2b0d14", "#3b1d00": "#2b0d14", "#4a2300": "#4a1a24", "#7a5a3a": "#7a5a52", "#c43c00": "#a31d2d" },
               rgb: { "238,98,0": "138,28,47", "255,154,0": "184,137,46", "59,29,0": "43,13,20", "42,20,0": "43,13,20" } } }
  };
  var lastKey = null;
  function hex(buf) { return Array.prototype.map.call(new Uint8Array(buf), function (b) { return ('0' + b.toString(16)).slice(-2); }).join(''); }
  function keyHash(key) {
    var enc = new TextEncoder();
    return crypto.subtle.importKey('raw', enc.encode(String(key).trim().toLowerCase()), 'PBKDF2', false, ['deriveBits'])
      .then(function (k) { return crypto.subtle.deriveBits({ name: 'PBKDF2', salt: enc.encode('moelab-brand-v1'), iterations: 60000, hash: 'SHA-256' }, k, 128); })
      .then(hex);
  }
  function currentKey() {
    try { var l = JSON.parse(localStorage.getItem('moe_offline_license') || 'null'); return l && l.key ? String(l.key) : ''; } catch (e) { return ''; }
  }
  function isLight(el) {
    try {
      var m = getComputedStyle(el).backgroundColor.match(/[\d.]+/g);
      if (!m) return false;
      var a = m.length > 3 ? parseFloat(m[3]) : 1; if (a === 0) return false;
      return (0.299 * m[0] + 0.587 * m[1] + 0.114 * m[2]) > 150;
    } catch (e) { return false; }
  }
  function remove() { var o = document.getElementById('brandLogoWrap'); if (o) o.remove(); }
  function show(b) {
    var hd = document.querySelector('header');
    if (!hd) return;
    remove();
    var w = document.createElement('div');
    w.id = 'brandLogoWrap';
    w.style.cssText = 'display:flex;align-items:center;gap:12px;margin-inline-end:14px;padding-inline-end:14px;border-inline-end:1px solid #2a3b57;flex-shrink:0';
    var im = document.createElement('img');
    var light = isLight(hd);
    im.src = light && b.logoDark ? b.logoDark : b.logo; im.alt = b.name;
    if (light) w.style.borderInlineEndColor = '#e6d6bd';
    im.style.cssText = 'height:40px;width:auto;max-width:42vw;display:block;object-fit:contain';
    w.appendChild(im);
    var first = hd.firstElementChild;
    var grp = document.createElement('div');
    grp.style.cssText = 'display:flex;align-items:center;min-width:0';
    hd.insertBefore(grp, first);
    grp.appendChild(w); grp.appendChild(first);
  }

  /* شعار الصفحة الرئيسية: تحت كارتات الصفوف */
  function removeHome() { var o = document.getElementById('brandHomeLogo'); if (o) o.remove(); }
  function showHome(b) {
    var list = document.querySelector('#gradesView .grades-list');
    if (!list) return;
    var o = document.getElementById('brandHomeLogo');
    if (o) { if (o.firstChild && o.firstChild.src === b.homeLogo) return; o.remove(); }
    var w = document.createElement('div');
    w.id = 'brandHomeLogo';
    w.style.cssText = 'display:flex;justify-content:center;align-items:center;margin:26px auto 8px;padding:0 12px';
    var im = document.createElement('img');
    im.src = b.homeLogo; im.alt = b.name;
    im.style.cssText = 'height:clamp(150px,34vh,260px);width:auto;max-width:78vw;display:block;object-fit:contain;filter:drop-shadow(0 6px 14px rgba(43,13,20,.22))';
    w.appendChild(im);
    list.parentNode.insertBefore(w, list.nextSibling);
  }

  /* ثيم الألوان: نعيد كتابة أنماط الصفحة بألوان المشترك ونضيفها في آخر الصفحة */
  var tintedEls = [], baseCss = null;
  function mapCss(css, t) {
    return css
      .replace(/#([0-9a-fA-F]{6})\b/g, function (m) { return t.hex[m.toLowerCase()] || m; })
      .replace(/rgba?\(\s*(\d+)\s*,\s*(\d+)\s*,\s*(\d+)/g, function (m, r, g, b) { var v = t.rgb[r + ',' + g + ',' + b]; return v ? m.slice(0, m.indexOf('(') + 1) + v : m; });
  }
  function retint(t) {
    var els = document.querySelectorAll('[style]');
    for (var i = 0; i < els.length; i++) {
      var e = els[i], st = e.getAttribute('style');
      if (e.id === 'brandHomeLogo' || (e.parentNode && e.parentNode.id === 'brandHomeLogo')) continue;
      var n = mapCss(st, t);
      if (n !== st) { if (!e.__brandOrig) { e.__brandOrig = st; tintedEls.push(e); } e.setAttribute('style', n); }
    }
  }
  function applyTheme(b) {
    var t = b.theme; if (!t) return;
    var st = document.getElementById('brandTheme');
    if (!st) {
      if (baseCss === null) {
        baseCss = '';
        var tags = document.querySelectorAll('style');
        for (var i = 0; i < tags.length; i++) if (tags[i].id !== 'brandTheme') baseCss += tags[i].textContent + '\n';
      }
      st = document.createElement('style'); st.id = 'brandTheme';
      st.textContent = mapCss(baseCss, t);
      (document.body || document.documentElement).appendChild(st);
      var mt = document.querySelector('meta[name="theme-color"]');
      if (mt) { mt.__o = mt.content; mt.content = t.hex['#ee6200'] || mt.content; }
    }
    retint(t);
  }
  function removeTheme() {
    var st = document.getElementById('brandTheme'); if (st) st.remove();
    var mt = document.querySelector('meta[name="theme-color"]'); if (mt && mt.__o) { mt.content = mt.__o; mt.__o = null; }
    while (tintedEls.length) { var e = tintedEls.pop(); if (e.__brandOrig != null) { e.setAttribute('style', e.__brandOrig); e.__brandOrig = null; } }
  }
  function apply(b) {
    if (b.logo) show(b); else remove();
    if (b.homeLogo) showHome(b); else removeHome();
    if (b.theme) applyTheme(b); else removeTheme();
  }
  function clearAll() { remove(); removeHome(); removeTheme(); }

  var curBrand = null;
  function check() {
    var k = currentKey();
    if (k === lastKey) { if (curBrand && curBrand.theme) applyTheme(curBrand); if (curBrand && curBrand.homeLogo) showHome(curBrand); return; }
    lastKey = k;
    curBrand = null;
    if (!k || !window.crypto || !crypto.subtle) { clearAll(); return; }
    keyHash(k).then(function (h) {
      if (currentKey() !== k) return;
      try { localStorage.setItem('moe_brand_cache', JSON.stringify({ k: k, h: h })); } catch (e) {}
      if (BRANDS[h]) { curBrand = BRANDS[h]; apply(curBrand); } else clearAll();
    }).catch(function () { clearAll(); });
  }
  /* تطبيق فوري من الذاكرة المؤقتة حتى لا تظهر الألوان القديمة لحظة التحميل */
  try {
    var c = JSON.parse(localStorage.getItem('moe_brand_cache') || 'null');
    if (c && c.k === currentKey() && BRANDS[c.h]) { curBrand = BRANDS[c.h]; lastKey = c.k; apply(curBrand); }
  } catch (e) {}
  check();
  setInterval(check, 1500);
})();
